"""Print a reviewed inline root operation. Never execute this user-owned helper as root."""
import os
ROOT_SOURCE = '"""Reviewed inline A/root operation; do not execute a downloaded user-owned file as root."""\nimport hashlib, http.client, json, os, re, stat, subprocess, time\nfrom pathlib import Path\n\nUNIT = \'jwk-aenv-ae9c626-node-a.service\'\nOTHER = \'jwk-aenv-ub-b019f27-node-a.service\'\nBASE = Path(\'/home/jwk/agent/deployments/agentenv-ae9c626-baseline\')\nRECEIPT = Path(\'/run/cow55-original-memlock-repair.json\')\nDROP = Path(\'/run/systemd/system\') / (UNIT + \'.d\') / \'90-cow55-memlock.conf\'\nPENDING = Path(\'/home/jwk/agent/relay/cow55-replay-node-a.pending.json\')\nLIMIT = 2147483648\n\ndef need(ok, message):\n    if not ok: raise RuntimeError(message)\n\ndef show(unit):\n    v = subprocess.run([\'/usr/bin/systemctl\',\'show\',unit,\'--no-pager\',\n        \'--property=MainPID,ActiveState,User,Group,LimitMEMLOCK,LimitMEMLOCKSoft\'],\n        capture_output=True,text=True,check=True,timeout=15)\n    return dict(x.split(\'=\',1) for x in v.stdout.splitlines() if \'=\' in x)\n\ndef identity(pid):\n    return [int(pid), Path(\'/proc/\'+str(pid)+\'/stat\').read_text().rsplit(\')\',1)[1].split()[19]]\n\ndef regular(path, uid, maximum):\n    need(path.resolve(strict=True)==path, \'Redirected input\')\n    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)\n    with os.fdopen(fd,\'rb\') as f:\n        s=os.fstat(f.fileno())\n        need(stat.S_ISREG(s.st_mode) and s.st_uid==uid and s.st_size<=maximum,\'Unexpected input file\')\n        data=f.read(maximum+1);need(len(data)<=maximum,\'Input grew\');return data\n\ndef get(path):\n    c=http.client.HTTPConnection(\'127.0.0.1\',18080,timeout=5)\n    try:\n        c.request(\'GET\',path,headers={\'X-API-Key\':key});v=c.getresponse();raw=v.read(65537)\n        need(len(raw)<=65536 and not v.getheader(\'x-next-token\'),\'Incomplete API response\')\n        return v.status,json.loads(raw) if raw else None\n    finally:c.close()\n\ndef no_guests(main):\n    need(get(\'/v2/sandboxes?limit=1\')==(200,[]),\'Original sandbox inventory not empty\')\n    parents={};names={}\n    for p in Path(\'/proc\').iterdir():\n        if not p.name.isdigit():continue\n        try:\n            fields=(p/\'stat\').read_text().rsplit(\')\',1)[1].split()\n            parents[int(p.name)]=int(fields[1]);names[int(p.name)]=(p/\'comm\').read_text().strip()\n        except (FileNotFoundError,ProcessLookupError):continue\n    owned={int(main)}\n    while True:\n        new={p for p,parent in parents.items() if parent in owned}-owned\n        if not new:break\n        owned.update(new)\n    need(not any(names.get(p)==\'firecracker\' for p in owned),\'Original Firecracker still present\')\n\ndef save():\n    tmp=RECEIPT.with_suffix(\'.tmp\')\n    with tmp.open(\'x\') as f:json.dump(result,f,indent=2);f.flush();os.fsync(f.fileno())\n    os.chmod(tmp,0o600);os.replace(tmp,RECEIPT)\n\nresult={\'revision\':\'cow55-original-memlock-repair-v1\',\'status\':\'PRECHECK\',\n        \'unit\':UNIT,\'new_limit_bytes\':LIMIT,\'SDK_called\':False,\'B_accessed\':False,\n        \'restarts_submitted\':0,\'dropin\':str(DROP)}\ntry:\n    need(os.geteuid()==0 and os.uname().nodename==\'server1\',\'A/root only\')\n    os.umask(0o077)\n    need(not RECEIPT.exists() and not RECEIPT.is_symlink(),\'Repair already recorded; do not repeat\')\n    need(not RECEIPT.with_suffix(\'.tmp\').exists(),\'Previous operation incomplete\')\n    before=show(UNIT);other=show(OTHER);other_id=identity(other[\'MainPID\'])\n    need(before[\'ActiveState\']==\'active\' and before[\'User\']==before[\'Group\']==\'jwk\',\'Unexpected original service\')\n    need(identity(before[\'MainPID\'])==[2464930,\'24073603\'],\'Original process changed\')\n    need(identity(2465365)==[2465365,\'24073667\'],\'Original daemon changed\')\n    need(before[\'LimitMEMLOCK\']==before[\'LimitMEMLOCKSoft\']==\'67108864\',\'Original limit changed\')\n    pending=regular(PENDING,1204,2*1024**2);old=json.loads(pending)\n    need(old[\'run_id\']==\'323ff7550463486f89ebf66264d39257\' and old[\'status\']==\'STOPPED_COW55_REPLAY\',\'Unexpected previous run\')\n    key=regular(BASE/\'config/api-key\',1204,1024).decode().strip()\n    need(re.fullmatch(r\'e2b_[A-Za-z0-9._~-]+\',key),\'Unexpected key format\')\n    config=regular(BASE/\'config/runtime.toml\',1204,65536)\n    for sid in (\'01a15d10-ed49-72a2-bb83-6763a755ff4c\',\'01a15d10-ef15-7ab0-9a5a-19a0b147cce7\'):\n        need(get(\'/sandboxes/\'+sid)[0]==404,\'Late request still exists\')\n    for _ in range(3):no_guests(before[\'MainPID\']);time.sleep(1)\n    result.update(original_before=identity(before[\'MainPID\']),modified_before=other_id,\n        previous_run_id=old[\'run_id\'],previous_pending_sha256=hashlib.sha256(pending).hexdigest(),\n        runtime_config_sha256=hashlib.sha256(config).hexdigest(),old_limit_bytes=67108864)\n    need(DROP.parent.parent.resolve()==DROP.parent.parent,\'Redirected systemd runtime directory\')\n    if DROP.parent.exists():\n        m=DROP.parent.lstat();need(stat.S_ISDIR(m.st_mode) and m.st_uid==0 and not m.st_mode&0o022,\'Unexpected drop-in directory\')\n    else:DROP.parent.mkdir(mode=0o755)\n    need(not DROP.exists() and not DROP.is_symlink(),\'Drop-in already exists\')\n    result[\'status\']=\'READY_TO_APPLY\';save()\n    with DROP.open(\'x\') as f:f.write(\'[Service]\\nLimitMEMLOCK=2147483648\\n\')\n    os.chmod(DROP,0o644)\n    subprocess.run([\'/usr/bin/systemctl\',\'daemon-reload\'],check=True,timeout=30)\n    need(identity(show(UNIT)[\'MainPID\'])==result[\'original_before\'],\'Original process changed during preparation\')\n    no_guests(before[\'MainPID\'])\n    result.update(status=\'RESTART_SUBMITTED\',restarts_submitted=1);save()\n    subprocess.run([\'/usr/bin/systemctl\',\'restart\',UNIT],check=True,timeout=180)\n    deadline=time.monotonic()+60\n    while time.monotonic()<deadline:\n        try:\n            if get(\'/health\')[0]==204:break\n        except (OSError,http.client.HTTPException):pass\n        time.sleep(1)\n    after=show(UNIT);new_id=identity(after[\'MainPID\'])\n    need(after[\'ActiveState\']==\'active\' and new_id!=result[\'original_before\'],\'Restart not confirmed\')\n    need(after[\'LimitMEMLOCK\']==after[\'LimitMEMLOCKSoft\']==str(LIMIT),\'New limit not applied\')\n    limits=Path(\'/proc/\'+str(new_id[0])+\'/limits\').read_text()\n    need(re.search(r\'Max locked memory\\s+2147483648\\s+2147483648\\s+bytes\',limits),\'Actual process limit differs\')\n    daemons=[]\n    for p in Path(\'/proc\').iterdir():\n        if not p.name.isdigit():continue\n        try:\n            fields=(p/\'stat\').read_text().rsplit(\')\',1)[1].split()\n            if int(fields[1])==new_id[0] and (p/\'comm\').read_text().strip()==\'uvm-ublk-daemon\':\n                need(re.search(r\'Max locked memory\\s+2147483648\\s+2147483648\\s+bytes\',(p/\'limits\').read_text()),\'New daemon limit differs\')\n                daemons.append(identity(int(p.name)))\n        except (FileNotFoundError,ProcessLookupError):continue\n    need(len(daemons)==1 and daemons[0]!=[2465365,\'24073667\'],\'Fresh daemon not verified\')\n    need(get(\'/health\')[0]==204,\'Original health not restored\');no_guests(new_id[0])\n    need(identity(show(OTHER)[\'MainPID\'])==other_id,\'Modified service process changed\')\n    need(regular(BASE/\'config/runtime.toml\',1204,65536)==config,\'Runtime configuration changed\')\n    need(regular(PENDING,1204,2*1024**2)==pending,\'Previous replay receipt changed\')\n    result.update(status=\'A_ORIGINAL_MEMLOCK_RESTART_VERIFIED\',original_after=new_id,\n        daemon_after=daemons[0],\n        actual_process_memlock_bytes=LIMIT,health=204,empty_inventory=True,\n        modified_process_unchanged=True,previous_pending_preserved=True)\n    save()\nexcept Exception as e:\n    result.update(status=\'STOPPED_MEMLOCK_REPAIR\',error_type=type(e).__name__,reason=str(e))\n    if \'key\' in globals():result[\'reason\']=result[\'reason\'].replace(key,\'[REDACTED]\')\n    if RECEIPT.exists() and result.get(\'original_before\'):save()\nprint(\'BEGIN_RETURN_REPORT\');print(json.dumps(result,indent=2));print(\'END_RETURN_REPORT\')\n'
if __name__ == '__main__':
    if os.geteuid() != 1204 or os.uname().nodename != 'server1':
        raise SystemExit('Run as ordinary A/jwk; copy the printed body to A/root after review')
    print('BEGIN_REVIEWED_ROOT_COPY_BODY_ONLY')
    print("/usr/bin/python3 -I -B - <<'COW55_MEMLOCK_REPAIR'")
